module chamfered_plate() {
    plate_length = 100;
    plate_width = 50;
    plate_thickness = 2;
    chamfer_size = 5;

    difference() {
        cube([plate_length, plate_width, plate_thickness], center = true);
        for (x_offset = [-1, 1])
            for (y_offset = [-1, 1])
                translate([x_offset * (plate_length / 2 - chamfer_size), y_offset * (plate_width / 2 - chamfer_size), 0])
                    cube([chamfer_size, chamfer_size, plate_thickness], center = false);
    }
}

chamfered_plate();

module rounded_rectangle(width, height, radius, thickness) {
    difference() {
        offset(r=radius) offset(delta=thickness)
            square([width-2*radius, height-2*radius], center=true);
        offset(r=radius)
            square([width, height], center=true);
    }
}

module cutout_grid(rows, cols, cutout_width, cutout_height, spacing) {
    for (i = [0:cols-1])
        for (j = [0:rows-1])
            translate([(i - (cols-1)/2) * (cutout_width + spacing), 
                       (j - (rows-1)/2) * (cutout_height + spacing), 0])
                rounded_rectangle(cutout_width, cutout_height, 0.01, 0.005);
}

module diagonal_ribs(width, height, thickness) {
    polygon(points=[
        [-width/2, -height/2], 
        [width/2, height/2], 
        [width/2, height/2-thickness], 
        [-width/2+thickness, -height/2]
    ]);
    polygon(points=[
        [-width/2, height/2], 
        [width/2, -height/2], 
        [width/2-thickness, -height/2], 
        [-width/2, height/2-thickness]
    ]);
}

module panel() {
    difference() {
        union() {
            rounded_rectangle(0.2, 0.1, 0.01, 0.005);
            diagonal_ribs(0.2, 0.1, 0.005);
        }
        cutout_grid(2, 3, 0.06, 0.03, 0.01);
    }
}

panel();

module stepped_bar() {
    // Define the dimensions of the segments
    segment_lengths = [0.05, 0.03, 0.04, 0.02, 0.06];
    segment_widths = [0.1, 0.15, 0.1, 0.15, 0.1];
    segment_heights = [0.1, 0.15, 0.1, 0.15, 0.1];

    // Initialize position
    position = 0;

    // Create the stepped bar
    for (i = [0 : len(segment_lengths) - 1]) {
        translate([position, 0, 0])
            cube([segment_lengths[i], segment_widths[i], segment_heights[i]], center = true);
        position += segment_lengths[i];
    }
}

// Center the object at the origin
