module rod_component() {
    union() {
        // Main ribbed cylindrical midsection
        translate([0, 0, -0.5])
        ribbed_cylinder(0.3, 0.9, 0.05, 0.02, 10);

        // Polygonal end caps
        translate([0, 0, -0.7])
