module faceted_cylinder(diameter, length, facets) {
    for (i = [0:facets-1]) {
        rotate([0, 0, i * 360 / facets])
        translate([0, 0, -length/2])
        cylinder(d1=diameter, d2=diameter * 0.95, h=length, $fn=3);
    }
}

