    difference() {
        cylinder(r=radius, h=thickness, $fn=64);
        for (i = [0:teeth-1]) {
            rotate([0, 0, i * 360 / teeth])
            translate([radius, 0, 0])
            cube([radius / teeth, 2 * radius / teeth, thickness], center=true);
        }
    }
