module hex_bore(size, thickness) {
    rotate([0, 0, 90])
    translate([0, 0, -thickness/2])
    linear_extrude(height=thickness)
    polygon(points=[
        [size/2, 0],
        [size/4, size * sqrt(3)/4],
        [-size/4, size * sqrt(3)/4],
        [-size/2, 0],
        [-size/4, -size * sqrt(3)/4],
        [size/4, -size * sqrt(3)/4]
    ]);
}

