module chamfered_cube(size, chamfer) {
    difference() {
        cube(size, center=true);
        for (x=[-1,1], y=[-1,1], z=[-1,1]) {
            translate([x*(size[0]/2-chamfer), y*(size[1]/2-chamfer), z*(size[2]/2-chamfer)])
                cube([chamfer*2, chamfer*2, chamfer*2], center=true);
        }
    }
}

