            translate([-0.025, -0.05, 0.025])
                chamfered_cube([0.05, 0.1, 0.05], 0.005);
        }
        translate([-0.05, -0.05, -0.05])
            cube([0.05, 0.05, 0.1], center=false);
        translate([-0.025, -0.05, 0.025])
