        translate([0, 0, 10])
            knurled_band(25, 5, 64);
        translate([0, 0, 15])
            serrated_cylinder(25, 10, 2, 12);
        translate([0, 0, 25])
            knurled_band(25, 5, 64);
        translate([0, 0, 30])
            serrated_cylinder(25, 10, 2, 12);
        translate([0, 0, 0])
            hex_bore(10, 40);
    }
}

